def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    prev_bids = []
    desperate_count = 0
    rich_count = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                desperate_count += 1
            if opp.get('budget', 0) >= 140:
                rich_count += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0))

    if not alive_opponents:
        return max(0.0, min(budget, DAILY_SALARY * 0.25))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    tight_supply = supply <= 17
    ample_supply = supply >= 22
    critical_me = hp <= 3 or no_water_days >= 1
    very_critical = hp <= 2 or no_water_days >= 2

    bid = DAILY_SALARY * 0.45

    if ample_supply:
        bid = DAILY_SALARY * 0.28
    elif tight_supply:
        bid = DAILY_SALARY * 0.62
    else:
        bid = DAILY_SALARY * 0.48

    if highest_prev >= 140:
        if critical_me:
            bid = max(bid, min(highest_prev + 2.0, DAILY_SALARY * 1.55))
        else:
            bid = min(bid, DAILY_SALARY * 0.35)
    elif highest_prev >= 95:
        if critical_me:
            bid = max(bid, min(highest_prev + 1.5, DAILY_SALARY * 1.2))
        else:
            bid = max(bid, avg_prev * 0.72)
    elif highest_prev > 0:
        bid = max(bid, min(highest_prev + 1.2, DAILY_SALARY * 0.95))

    if desperate_count >= 2:
        bid += 10.0
    elif desperate_count == 1:
        bid += 4.0

    if rich_count >= 2 and tight_supply:
        bid += 8.0

    if critical_me:
        bid = max(bid, DAILY_SALARY * 0.92)
    if very_critical:
        bid = max(bid, DAILY_SALARY * 1.12)

    if day >= 8 and hp >= 6 and not tight_supply:
        bid *= 0.88

    if budget < DAILY_SALARY * 1.2:
        bid = min(bid, budget * 0.82)
    elif budget > 300 and critical_me:
        bid = max(bid, DAILY_SALARY * 1.05)

    if bid < 0:
        bid = 0.0
    if bid > budget:
        bid = budget
    return float(max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append((oid, o))

    if not alive_opps:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Read yesterday immediate pressure from previous_trace
    prev_bids = []
    prev_hp_after = []
    for oid, o in alive_opps:
        pt = o.get('previous_trace', {}) or {}
        bid = pt.get('bid', None)
        if bid is not None:
            try:
                prev_bids.append(float(bid))
            except Exception:
                pass
        try:
            if pt.get('hp_after', None) is not None:
                prev_hp_after.append(float(pt.get('hp_after')))
        except Exception:
            pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Supply pressure: with supply 15-25, water units are usually 1-2 for us.
    # We aim to buy enough water to avoid losing another HP step.
    # Approx mapping: if supply is low, winning water is more valuable.
    supply_units = int(supply / float(WATER_REQ))  # safe int index not needed; just compute
    # If supply < 18, likely 1 unit max; otherwise 2.

    # Determine base bid aggressiveness
    # If someone previously bid very high, they were likely trying to secure scarce water.
    high_pressure = highest_prev_bid >= DAILY_SALARY * 0.85

    # HP urgency
    if hp <= 2.5 or no_water_days >= 2:
        urgency = 1.0
    elif hp <= 4.0:
        urgency = 0.7
    else:
        urgency = 0.4

    # Conservative baseline to avoid Cindy-like failure mode
    # When not high pressure and our HP is healthy, keep bid below typical survival bids.
    if high_pressure:
        # Compete but not max; attempt to outbid only slightly.
        target = min(budget, max(DAILY_SALARY * 0.55, highest_prev_bid * 0.92 + 2.0))
    else:
        # If supply is low, slightly increase bid; else keep low.
        if supply < 18.0:
            target = DAILY_SALARY * (0.48 + 0.25 * urgency)
        else:
            target = DAILY_SALARY * (0.40 + 0.22 * urgency)

    # Ensure we don't overspend when budget is tight
    # Also cap by a fraction of budget to preserve future rounds.
    budget_cap = budget * 0.65 if budget > 0 else 0.0
    target = min(target, budget_cap)

    # If our budget is extremely small, bid whatever we can.
    if budget <= DAILY_SALARY * 0.12:
        return max(0.0, min(budget, DAILY_SALARY * 0.2))

    # Final safety: never negative
    return max(0.0, float(target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    my_current_hp = my_status['hp']
    my_current_budget = my_status['budget']
    current_supply = day_context['supply']

    base_bid = DAILY_SALARY * 0.55

    supply_factor = (current_supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    inverse_supply_factor = 1 - supply_factor

    base_bid += inverse_supply_factor * (DAILY_SALARY * 0.2)

    if my_current_hp <= 2:
        bid = DAILY_SALARY * 0.98
    elif my_current_hp <= 4:
        bid = DAILY_SALARY * 0.85
    elif my_current_hp <= 6:
        bid = DAILY_SALARY * 0.75
    else:
        bid = base_bid

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if my_current_hp > 4:
            bid = max(bid, highest_prev_bid + 5)
            bid = min(bid, DAILY_SALARY * 0.9)
        else:
            bid = max(bid, highest_prev_bid + 10)
            bid = min(bid, DAILY_SALARY * 0.99)

    bid = min(bid, my_current_budget)

    if bid < 1.0 and my_current_budget > 0:
        bid = 1.0

    return max(0.0, bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    prev_bids = []
    for opp in alive_opponents:
        trace = opp.get('previous_trace')
        if trace and trace.get('bid') is not None:
            prev_bids.append(trace['bid'])
    if my_status['hp'] <= 3:
        base_bid = DAILY_SALARY * 0.9
    else:
        if prev_bids:
            highest_prev = max(prev_bids)
            base_bid = highest_prev + 2.0
        else:
            base_bid = DAILY_SALARY * 0.6
    bid = min(my_status['budget'], DAILY_SALARY, base_bid)
    if my_status['no_water_days'] > 0:
        bid = min(my_status['budget'], DAILY_SALARY, max(bid, DAILY_SALARY * 0.95))
    return max(0, bid)
